from PIL import Image
im=Image.open('/home/robot/captures/top_001.png').convert('L')
w,h=im.size
px=im.load()
# threshold bright maybe >180
mask=[[False]*w for _ in range(h)]
for y in range(h):
    for x in range(w):
        if px[x,y]>180:
            mask[y][x]=True
# BFS components
seen=[[False]*w for _ in range(h)]
comps=[]
for y in range(h):
    for x in range(w):
        if mask[y][x] and not seen[y][x]:
            stack=[(x,y)]; seen[y][x]=True; pts=[]
            while stack:
                cx,cy=stack.pop(); pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not seen[ny][nx]:
                        seen[ny][nx]=True; stack.append((nx,ny))
            if len(pts)>30:
                sx=sum(p[0] for p in pts)/len(pts); sy=sum(p[1] for p in pts)/len(pts)
                comps.append((len(pts),sx,sy,min(p[0] for p in pts),max(p[0] for p in pts),min(p[1] for p in pts),max(p[1] for p in pts)))
comps.sort(reverse=True)
for c in comps[:50]:
    print('area',c[0],'cent', (round(c[1],1),round(c[2],1)), 'bbox', c[3:])
print('count',len(comps))
